```
دالة سطّح_القائمة(ق) {
    متغير م = []
    من_أجل (ع في ق) {
        إذا كان نوع(ع) == "قائمة" {
            م = م + سطّح_القائمة(ع)
        } آخر {
            م = م + [ع]
        }
    }
    ارجع م
}
```

